#include "Power.h"
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;
using K=MachineKind;using E=EnergyMedium;
static int checks=0;
static void require(bool yes,const char* message){++checks;if(!yes)throw std::runtime_error(message);}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.electricity=100000;f.water=10000;f.farmProduce=1000;f.chemicals=100;return f;}
static Machine& device(Factory& f,Position p,K k,int dir=0){Machine m;m.kind=k;m.dir=dir;m.duration=std::max(1,machineSpec(k).duration);if(isEnergyMachine(k))initialisePowerDevice(m);return f.machines.emplace(p,m).first->second;}
static void line(Factory& f,Position a,Position b,E e,double rating=100){for(int n=0;n<1000;n++){if(!f.energyLink(a,e)){PowerLink l;l.medium=e;l.rating=rating;f.energyLinks[a].push_back(l);}if(a==b)return;if(a.x!=b.x)a.x+=a.x<b.x?1:-1;else a.y+=a.y<b.y?1:-1;}throw std::runtime_error("test route exceeds bound");}
static Batch food(Factory& f,const std::string& ingredient,double grams){Batch b;b.id=f.nextId++;addIngredient(b.food,ingredient,grams,f.nextComponent++,f.nextOperation++);b.matter=projectCell(b.food);return b;}
static double sum(const Factory& f,E e){double result=0;for(const auto& [p,m]:f.machines)result+=m.power.store[size_t(e)];return result;}
int main(int argc,char** argv){try{
 {auto f=empty();device(f,{0,0},K::SolarPanel);auto& load=device(f,{4,0},K::GrowLight);f.beginPowerStep();require(f.grid.active&&!f.powerAvailable({4,0},machineSpec(load.kind).power),"disconnected source cannot use the legacy input buffer");f.finishPowerStep();require(f.electricity==100000,"physical grid does not silently import electricity");}
 {auto f=empty();device(f,{0,0},K::SolarPanel);device(f,{4,0},K::GrowLight);line(f,{1,0},{4,0},E::AC);f.beginPowerStep();require(!f.powerAvailable({4,0},1),"solar DC cannot feed an AC consumer");}
 {auto f=empty();device(f,{0,0},K::SolarPanel);device(f,{3,0},K::Inverter);device(f,{7,0},K::GrowLight);line(f,{1,0},{2,0},E::DC);line(f,{4,0},{7,0},E::AC);f.beginPowerStep();double draw=machineSpec(K::GrowLight).power;require(f.powerAvailable({7,0},draw),"correctly connected inverter supplies actual load");double reserve=f.electricity;f.usePower({7,0},draw);f.finishPowerStep();require(std::abs(f.grid.delivered-draw)<1e-6&&f.grid.loss>0&&f.electricity==reserve,"real delivery consumes generation with cable and converter losses");require(f.energyLink({5,0},E::AC)->flow>0,"only actual transfers light the floor route");}
 {auto f=empty();auto& pv=device(f,{0,0},K::SolarPanel);device(f,{3,0},K::Inverter,2);device(f,{7,0},K::GrowLight);line(f,{1,0},{2,0},E::DC);line(f,{4,0},{7,0},E::AC);f.beginPowerStep();require(pv.power.generated>0&&!f.powerAvailable({7,0},1),"rotated physical terminals prevent a backwards connection");}
 {auto f=empty();device(f,{0,0},K::WindRotor);device(f,{2,0},K::Gearbox);auto& gen=device(f,{4,0},K::Alternator);line(f,{1,0},{1,0},E::Shaft);line(f,{3,0},{3,0},E::Shaft);f.beginPowerStep();require(gen.power.generated>0,"wind drives gearbox and alternator through separate shaft ports");double amount=gen.power.generated;f.finishPowerStep();f.at({2,0})->enabled=false;f.at({4,0})->power.store.fill(0);f.beginPowerStep();require(f.at({4,0})->power.generated==0&&amount>0,"an isolated gearbox cannot act as a passive shaft bypass");}
 {auto f=empty();auto& b=device(f,{0,0},K::BatteryRack);b.power.store[size_t(E::DC)]=12;device(f,{3,0},K::Inverter);device(f,{7,0},K::GrowLight);line(f,{1,0},{2,0},E::DC);line(f,{4,0},{7,0},E::AC);double start=sum(f,E::DC)+sum(f,E::AC),delivered=0;for(int n=0;n<100;n++){f.beginPowerStep();f.usePower({7,0},machineSpec(K::GrowLight).power);delivered+=f.grid.delivered;f.finishPowerStep();}require(delivered>0&&delivered<start&&sum(f,E::DC)+sum(f,E::AC)<.1,"finite battery cannot power a load indefinitely or charge itself");}
 {auto f=empty();auto& inlet=device(f,{0,0},K::GridInlet);inlet.power.rate=50;device(f,{3,0},K::Switchboard);device(f,{7,0},K::GrowLight);line(f,{1,0},{2,0},E::AC);line(f,{4,0},{7,0},E::AC);f.beginPowerStep();require(f.powerAvailable({7,0},1),"closed switchboard carries supply");f.finishPowerStep();f.at({3,0})->enabled=false;f.beginPowerStep();require(!f.powerAvailable({7,0},1),"opening switchboard isolates its downstream circuit");}
 {auto f=empty();auto& inlet=device(f,{0,0},K::GridInlet);inlet.power.rate=100;device(f,{5,0},K::Heater).item=food(f,"brine",100);line(f,{1,0},{5,0},E::AC,1);for(int n=0;n<100;n++){f.beginPowerStep();f.usePower({5,0},machineSpec(K::Heater).power);f.finishPowerStep();}require(f.energyLink({2,0},E::AC)->tripped,"sustained undersized electrical route trips on overload");require(!f.powerAvailable({5,0},1),"tripped route carries no fresh supply");for(auto& [p,links]:f.energyLinks)for(auto& l:links)l.enabled=false;for(int n=0;n<70;n++){f.beginPowerStep();f.finishPowerStep();}require(f.configureEnergyLink({2,0},E::AC,"reset")&&!f.energyLink({2,0},E::AC)->tripped,"isolated conductor can cool and reset");}
 {auto f=empty();auto& boiler=device(f,{0,0},K::BiomassBoiler);boiler.item=food(f,"cocoa",100);auto& water=device(f,{0,-3},K::FeedPump);water.enabled=false;double initial=analyse(boiler.item->food).mass;f.beginPowerStep();require(analyse(boiler.item->food).mass==initial&&boiler.power.store[size_t(E::Steam)]==0,"unpowered cold boiler holds its actual fuel");}
 {auto f=empty();auto& boiler=device(f,{0,0},K::BiomassBoiler);boiler.item=food(f,"cocoa",100);boiler.power.temperature=120;auto& water=device(f,{0,-3},K::FeedPump);water.power.store[size_t(E::Water)]=10;line(f,{1,-3},{1,-1},E::Water);line(f,{1,-1},{0,-1},E::Water);double initial=analyse(boiler.item->food).mass;f.beginPowerStep();require(analyse(boiler.item->food).mass<initial&&boiler.power.store[size_t(E::Steam)]>0,"warm boiler consumes organic matter and actual supplied water");double burnt=f.grid.ventedMass;double mass=analyse(boiler.item->food).mass;require(std::abs(initial-mass-burnt)<1e-6,"burned fuel is accounted as vented mass");}
 {auto f=empty();auto& accumulator=device(f,{0,0},K::SteamAccumulator);accumulator.power.store[size_t(E::Steam)]=5;auto& turbine=device(f,{2,0},K::SteamTurbine);line(f,{1,0},{1,0},E::Steam);f.beginPowerStep();require(turbine.power.store[size_t(E::Shaft)]>0&&std::abs(turbine.power.store[size_t(E::Exhaust)]-(5-accumulator.power.store[size_t(E::Steam)]-5*.002))<1e-6,"steam turbine preserves working-fluid mass while producing shaft work");double shaft=turbine.power.store[size_t(E::Shaft)];turbine.power.store[size_t(E::Exhaust)]=turbine.power.capacity;accumulator.power.store[size_t(E::Steam)]=5;f.beginPowerStep();require(turbine.power.store[size_t(E::Shaft)]==shaft,"blocked exhaust prevents new turbine work");}
 {auto f=empty();auto& digester=device(f,{0,0},K::AnaerobicDigester);digester.duration=1;digester.item=food(f,"greens",100);double mass=analyse(digester.item->food).mass;f.beginPowerStep();require(digester.sideOutput&&digester.sideOutput->residue=="digestate","digestion retains a real non-food side residue");double after=analyse(digester.sideOutput->food).mass;require(std::abs(mass-after-digester.power.store[size_t(E::RawGas)]-f.grid.ventedMass)<1e-6,"gas yield removes the same organic mass from feed");}
 {auto f=empty();auto& gas=device(f,{0,0},K::GasHolder);gas.power.store[size_t(E::Gas)]=10;auto& engine=device(f,{2,0},K::GasEngine);line(f,{1,0},{1,0},E::Gas);f.beginPowerStep();require(engine.power.store[size_t(E::Shaft)]==0,"gas engine requires explicit black-start energy");engine.power.rpm=1000;f.beginPowerStep();require(engine.power.store[size_t(E::Shaft)]>0&&gas.power.store[size_t(E::Gas)]<10,"running engine consumes finite clean fuel");}
 {auto f=empty();device(f,{0,0},K::GridInlet).power.rate=1;auto& a=device(f,{4,0},K::GrowLight);auto& b=device(f,{4,2},K::GrowLight);a.power.priority=0;b.power.priority=2;line(f,{1,0},{4,0},E::AC);line(f,{4,0},{4,2},E::AC);f.beginPowerStep();require(a.power.voltage>b.power.voltage,"critical loads get scarce supply before optional loads");}
 {auto f=empty();auto& b=device(f,{0,0},K::BatteryRack);b.power.store[size_t(E::DC)]=100;device(f,{3,0},K::Inverter);line(f,{1,0},{2,0},E::DC);require(f.captureBlueprint({0,0},{3,0},"power plan"),"capture actual energy arrangement");const auto& plan=f.blueprints.back();require(plan.links.size()==2,"plans retain typed material routes");require(f.stamp(plan,{10,10}),"stamp saved installation");require(f.at({10,10})->power.store[size_t(E::DC)]==0&&f.energyLink({11,10},E::DC),"plans preserve connections but cannot duplicate stored energy");auto rotated=Factory::rotatedBlueprint(plan);require(rotated.links.size()==plan.links.size()&&rotated.parts.front().machine.dir==1,"rotation retains conduit topology and turns ports");}
 {Factory f;f.water=100000;f.farmProduce=10000;f.chemicals=100;double output=0,delivered=0;int supply=0;for(int n=0;n<720;n++){f.step();output+=f.grid.generated;delivered+=f.grid.delivered;if(f.grid.delivered>0)supply++;}std::cout<<"Demo: generated "<<output<<", delivered "<<delivered<<", supplied ticks "<<supply<<", food served "<<f.shipped<<"\n";require(output>500&&delivered>200&&supply>500,"hybrid demo supplies real factory loads across two day-night cycles");require(std::any_of(f.machines.begin(),f.machines.end(),[](const auto& p){return p.second.kind==K::BiomassBoiler&&p.second.power.temperature>30;}),"demo includes functioning thermal generation");}
 {auto f=empty();device(f,{0,0},K::GridInlet);auto& tank=device(f,{0,3},K::HeatTank);tank.power.store[size_t(E::Heat)]=50;auto& h=device(f,{5,0},K::Heater);h.item=food(f,"brine",100);line(f,{1,0},{5,0},E::AC);line(f,{1,3},{5,3},E::Heat);line(f,{5,3},{5,0},E::Heat);f.beginPowerStep();f.usePower({5,0},machineSpec(K::Heater).power);f.finishPowerStep();require(f.grid.recoveredHeat>0&&tank.power.store[size_t(E::Heat)]<50,"thermal recovery replaces a measured part of electrical heating demand");}
 {auto f=empty();auto& battery=device(f,{0,0},K::BatteryRack);auto& inverter=device(f,{3,0},K::Inverter);auto& relay=device(f,{6,0},K::PowerRelay);auto& engine=device(f,{9,0},K::GasEngine);line(f,{1,0},{2,0},E::DC);line(f,{4,0},{8,0},E::AC);line(f,{8,0},{8,-1},E::AC);line(f,{8,-1},{9,-1},E::AC);battery.power.store[size_t(E::DC)]=battery.power.capacity*.8;f.beginPowerStep();require(!relay.power.armed&&!engine.power.armed,"relay stops automatic reserve generation above high threshold");battery.power.store[size_t(E::DC)]=battery.power.capacity*.5;f.beginPowerStep();require(!relay.power.armed,"relay hysteresis holds its previous dispatch between thresholds");battery.power.store[size_t(E::DC)]=battery.power.capacity*.1;f.beginPowerStep();require(relay.power.armed&&engine.power.armed,"relay starts reserve generation below low threshold");(void)inverter;}
 auto folder=std::filesystem::temp_directory_path()/"aftertaste-power-tests";std::filesystem::create_directories(folder);
 {Factory f;f.storageFile=folder/"save.json";require(f.save(),"save physical power state");Factory loaded;loaded.storageFile=f.storageFile;require(loaded.load()&&json(static_cast<FactoryState&>(loaded))==json(static_cast<FactoryState&>(f)),"power equipment, storage and layered routes survive reload exactly");}
 {Factory f;for(int n=0;n<80;n++)f.step();f.storageFile=folder/"running.json";require(f.save(),"save a running hybrid installation with fuel and residues");Factory loaded;loaded.storageFile=f.storageFile;require(loaded.load(),"processed power by-products remain valid persisted material");auto before=json(static_cast<FactoryState&>(loaded));auto invalid=before;invalid["blueprints"].back()["links"][0]["link"]["rating"]=-2;{std::ofstream out(f.storageFile);out<<json{{"version",9},{"factory",invalid}};}require(!loaded.load()&&json(static_cast<FactoryState&>(loaded))==before,"invalid saved energy routes are rejected atomically");}
 if(argc>1){std::ifstream in(argv[1]);json j;in>>j;auto old=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"load supplied legacy factory");for(const auto& [p,m]:old.machines)require(f.at(p)&&json(*f.at(p))==json(m),"legacy equipment, live food and growing crops are preserved exactly");double reserve=0;for(const auto& [p,m]:f.machines)if(m.kind==K::BatteryRack)reserve+=m.power.store[size_t(E::DC)];require(std::abs(f.electricity+reserve-old.electricity)<1e-6&&f.water==old.water&&f.chemicals==old.chemicals,"legacy migration transfers existing energy without changing other resources");require(f.save(),"save upgraded factory");auto state=json(static_cast<FactoryState&>(f));Factory again;again.storageFile=f.storageFile;require(again.load()&&json(static_cast<FactoryState&>(again))==state,"reloading cannot duplicate the district or startup reserves");}
 std::filesystem::remove_all(folder);std::cout<<"PASS physical power: "<<checks<<" checks\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL power: "<<error.what()<<" (check "<<checks<<")\n";return 1;}}
